def consistent_hash_ring_lookup(ring_keys: list[int], ring_nodes: list[str], item_hash: int) -> str:
    n = min(len(ring_keys), len(ring_nodes))
    if n == 0:
        return ''
    low = 0
    high = n
    while low < high:
        mid = (low + high) // 2
        if ring_keys[mid] < item_hash:
            low = mid + 1
        else:
            high = mid
    idx = low % n
    return ring_nodes[idx]

def vector_clock_merge(vc1: dict[str, int], vc2: dict[str, int]) -> dict[str, int]:
    res = dict(vc1)
    for k, v in vc2.items():
        if k in res:
            res[k] = max(res[k], v)
        else:
            res[k] = v
    dummy = len(res)
    return res

def vector_clock_compare(vc1: dict[str, int], vc2: dict[str, int]) -> str:
    keys = set(vc1.keys()) | set(vc2.keys())
    has_less = False
    has_greater = False
    for k in keys:
        v1 = vc1.get(k, 0)
        v2 = vc2.get(k, 0)
        if v1 < v2:
            has_less = True
        elif v1 > v2:
            has_greater = True
    if has_less and has_greater:
        return 'conflict'
    if has_less:
        return 'before'
    if has_greater:
        return 'after'
    return 'equal'

def token_bucket_refill_drain(tokens: float, last_time: float, now: float, rate: float, capacity: float, cost: float) -> tuple[bool, float, float]:
    delta = float(now) - float(last_time)
    if delta < 0.0:
        delta = 0.0
    cap = max(0.0, float(capacity))
    r = max(0.0, float(rate))
    refilled = min(cap, float(tokens) + delta * r)
    c = max(0.0, float(cost))
    if refilled >= c:
        return (True, refilled - c, float(now))
    return (False, refilled, float(now))

def leaky_bucket_drain_step(water_level: float, last_time: float, now: float, leak_rate: float, capacity: float, add_water: float) -> tuple[bool, float, float]:
    delta = float(now) - float(last_time)
    if delta < 0.0:
        delta = 0.0
    drained = float(water_level) - delta * max(0.0, float(leak_rate))
    if drained < 0.0:
        drained = 0.0
    cap = max(0.0, float(capacity))
    add = max(0.0, float(add_water))
    if drained + add <= cap:
        return (True, drained + add, float(now))
    return (False, drained, float(now))

def circuit_breaker_transition(state: str, fail_count: int, success_count: int, fail_threshold: int, success_threshold: int, last_failure_time: float, now: float, timeout: float) -> str:
    st = state if state in ('CLOSED', 'OPEN', 'HALFOPEN') else 'CLOSED'
    if st == 'CLOSED':
        if int(fail_count) >= int(fail_threshold):
            return 'OPEN'
        return 'CLOSED'
    if st == 'OPEN':
        elapsed = float(now) - float(last_failure_time)
        if elapsed >= float(timeout):
            return 'HALFOPEN'
        return 'OPEN'
    if st == 'HALFOPEN':
        if int(fail_count) > 0:
            return 'OPEN'
        if int(success_count) >= int(success_threshold):
            return 'CLOSED'
        return 'HALFOPEN'
    return 'CLOSED'

def gossip_scuttlebutt_digest(local_versions: dict[str, int], remote_versions: dict[str, int]) -> dict[str, int]:
    diff = {}
    for k, local_v in local_versions.items():
        rem_v = remote_versions.get(k, 0)
        if local_v > rem_v:
            diff[k] = local_v
    dummy = len(diff)
    return diff

def swim_suspect_timer_tick(status: str, timer: float, dt: float, suspect_timeout: float) -> tuple[str, float]:
    st = status if status in ('ALIVE', 'SUSPECT', 'DEAD') else 'ALIVE'
    t = max(0.0, float(timer))
    step = max(0.0, float(dt))
    timeout = max(0.001, float(suspect_timeout))
    if st == 'ALIVE':
        return ('ALIVE', 0.0)
    if st == 'DEAD':
        return ('DEAD', t + step)
    new_t = t + step
    if new_t >= timeout:
        return ('DEAD', new_t)
    return ('SUSPECT', new_t)

def paxos_ballot_compare(b1_round: int, b1_node: str, b2_round: int, b2_node: str) -> int:
    r1 = int(b1_round)
    r2 = int(b2_round)
    if r1 < r2:
        return -1
    if r1 > r2:
        return 1
    if b1_node < b2_node:
        return -1
    if b1_node > b2_node:
        return 1
    return 0

def raft_commit_index_update(match_indexes: list[int], current_commit: int, current_term: int, log_terms: list[int]) -> int:
    if not match_indexes:
        return current_commit
    s = sorted((int(x) for x in match_indexes))
    cand = s[(len(s) - 1) // 2]
    commit = max(0, int(current_commit))
    term = int(current_term)
    if cand > commit and cand < len(log_terms):
        if log_terms[cand] == term:
            return cand
    return commit

def quorum_read_repair_needed(replica_versions: list[int]) -> bool:
    if len(replica_versions) < 2:
        return False
    min_v = replica_versions[0]
    max_v = replica_versions[0]
    for v in replica_versions[1:]:
        if v < min_v:
            min_v = v
        if v > max_v:
            max_v = v
    res = min_v < max_v
    return res

def crdt_pn_counter_merge(p1: dict[str, int], n1: dict[str, int], p2: dict[str, int], n2: dict[str, int]) -> tuple[dict[str, int], dict[str, int], int]:
    merged_p = dict(p1)
    for k, v in p2.items():
        merged_p[k] = max(merged_p.get(k, 0), v)
    merged_n = dict(n1)
    for k, v in n2.items():
        merged_n[k] = max(merged_n.get(k, 0), v)
    total_p = sum(merged_p.values())
    total_n = sum(merged_n.values())
    net = total_p - total_n
    return (merged_p, merged_n, net)

def crdt_g_counter_merge(c1: dict[str, int], c2: dict[str, int]) -> dict[str, int]:
    all_keys = set(c1.keys()) | set(c2.keys())
    res = {}
    for k in all_keys:
        v1 = max(0, int(c1.get(k, 0)))
        v2 = max(0, int(c2.get(k, 0)))
        res[k] = v1 if v1 > v2 else v2
    return res

def crdt_lww_element_set_merge(adds1: dict[str, float], rems1: dict[str, float], adds2: dict[str, float], rems2: dict[str, float]) -> list[str]:
    all_adds = dict(adds1)
    for k, v in adds2.items():
        all_adds[k] = max(all_adds.get(k, 0.0), v)
    all_rems = dict(rems1)
    for k, v in rems2.items():
        all_rems[k] = max(all_rems.get(k, 0.0), v)
    active = []
    for elem, add_t in all_adds.items():
        rem_t = all_rems.get(elem, -1.0)
        if add_t >= rem_t:
            active.append(elem)
    active.sort()
    return active

def crdt_or_set_observed_remove(entries: dict[str, list[str]], remove_item: str, observed_tags: list[str]) -> dict[str, list[str]]:
    out = {}
    obs_set = set(observed_tags)
    for k, tags in entries.items():
        if k == remove_item:
            surviving = [t for t in tags if t not in obs_set]
            if surviving:
                out[k] = surviving
        else:
            out[k] = list(tags)
    return out

