def merkle_dag_root_hash(node_hashes: list[int], edge_pairs: list[list[int]]) -> int:
    h = 21661 * 100000 + 36261
    mask = (1 << 31) - 1
    for nh in node_hashes:
        val = abs(int(nh))
        h = (h ^ val) * 16777619 & mask
    for edge in edge_pairs:
        if len(edge) >= 2:
            u = abs(int(edge[0]))
            v = abs(int(edge[1]))
            h = (h ^ u + 1) * 16777619 & mask
            h = (h ^ v + 3) * 16777619 & mask
    return h

def anti_entropy_bloom_exchange(local_keys: list[str], bloom_filter_bits: list[int], num_bits: int, num_hashes: int) -> list[str]:
    m = max(1, int(num_bits))
    k = max(1, min(10, int(num_hashes)))
    n_filter = len(bloom_filter_bits)
    missing = []
    mask = (1 << 31) - 1
    salt = 10139 * 100000 + 4223
    for key in local_keys:
        is_present = True
        base_h = 21661 * 100000 + 36261
        for ch in key:
            base_h = (base_h ^ ord(ch)) * 16777619 & mask
        for i in range(k):
            bit_idx = (base_h + i * salt) % m
            if bit_idx < n_filter:
                if bloom_filter_bits[bit_idx] == 0:
                    is_present = False
                    break
            else:
                is_present = False
                break
        if not is_present:
            missing.append(key)
    return missing

def count_min_sketch_point_estimate(table: list[list[int]], item_hashes: list[int]) -> int:
    d = min(len(table), len(item_hashes))
    if d == 0:
        return 0
    max_sentinel = 1 << 30
    min_est = max_sentinel
    for i in range(d):
        row = table[i]
        if row:
            w = len(row)
            col = abs(int(item_hashes[i])) % w
            val = row[col]
            if val < min_est:
                min_est = val
    if min_est == max_sentinel:
        return 0
    return min_est

def hyperloglog_cardinality_raw(registers: list[int], m: int) -> float:
    m_val = max(1, int(m))
    if not registers:
        return 0.0
    if m_val == 16:
        alpha = 0.673
    elif m_val == 32:
        alpha = 0.697
    elif m_val == 64:
        alpha = 0.709
    else:
        alpha = 0.7213 / (1.0 + 1.079 / float(m_val))
    z = 0.0
    for r in registers:
        clamped_r = max(0, min(32, int(r)))
        z += 2.0 ** (-clamped_r)
    if z <= 0.0:
        return 0.0
    raw = alpha * float(m_val * m_val) / z
    return raw

def hyperloglog_bias_correction(raw_est: float, m: int, zero_registers: int) -> float:
    e = max(0.0, float(raw_est))
    m_val = max(1, int(m))
    v = max(0, int(zero_registers))
    if e <= 2.5 * float(m_val):
        if v > 0:
            frac = float(m_val) / float(v)
            return float(m_val) * math.log(frac)
        return e
    return e

def fountain_lt_degree_distribution(k: int, rand_val: float) -> int:
    k_val = max(1, int(k))
    if k_val == 1:
        return 1
    u = max(0.0, min(0.999999, float(rand_val)))
    prob1 = 1.0 / float(k_val)
    if u < prob1:
        return 1
    cum = prob1
    for d in range(2, k_val + 1):
        p_d = 1.0 / float(d * (d - 1))
        cum += p_d
        if u < cum:
            return d
    return k_val

def bulkhead_slot_reservation(active_slots: int, max_slots: int, queue_len: int, max_queue: int) -> tuple[bool, str]:
    act = max(0, int(active_slots))
    m_act = max(1, int(max_slots))
    q = max(0, int(queue_len))
    m_q = max(0, int(max_queue))
    if act < m_act:
        return (True, 'ACTIVE')
    if q < m_q:
        return (True, 'QUEUED')
    return (False, 'REJECTED')
